<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require 'includes/toasts.php'; require_staff_or_admin($pdo);
$messages=[]; $flash=$_SESSION['flash_success']??null; $error=$_SESSION['flash_error']??null; unset($_SESSION['flash_success'],$_SESSION['flash_error']); if ($flash) $messages[]=['kind'=>'success','text'=>$flash]; if ($error) $messages[]=['kind'=>'danger','text'=>$error];
$orders=$pdo->query("SELECT o.order_id,o.order_number,o.user_id,o.fulfillment,o.customer_name,o.phone,o.delivery_address,o.delivery_instructions,o.pickup_location,o.scheduled_for,o.payment_method,o.subtotal,o.delivery_fee,o.total,o.status,o.payment_status,o.created_at,(SELECT GROUP_CONCAT(CONCAT(i.quantity,' × ',i.item_name) ORDER BY i.order_item_id SEPARATOR ' · ') FROM customer_order_items i WHERE i.order_id=o.order_id) AS item_summary,(SELECT a.cancellation_reason FROM staff_order_actions a WHERE a.order_id=o.order_id AND a.event_type='cancelled' ORDER BY a.action_id DESC LIMIT 1) AS cancellation_reason FROM customer_orders o ORDER BY CASE WHEN LOWER(o.status) IN ('pending','confirmed','preparing','ready','out_for_delivery') THEN 0 ELSE 1 END,o.created_at DESC")->fetchAll();
$transitions=['pending'=>['confirmed'],'confirmed'=>['preparing'],'preparing'=>['ready'],'ready'=>[],'out_for_delivery'=>['completed']];
$reasonLabels=['customer_request'=>'Customer request','item_unavailable'=>'Item unavailable','payment_issue'=>'Payment issue','duplicate_order'=>'Duplicate order','delivery_issue'=>'Delivery issue','other'=>'Other operational reason'];
$pageTitle='Incoming orders'; require 'includes/header.php'; render_toasts($messages);
?>
<main class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="text-uppercase small fw-semibold text-secondary mb-1">Staff and admin</p><h1 class="mb-1">Incoming orders</h1><p class="text-secondary mb-0">Customer contact and address details are shown here for order handling.</p></div><a class="btn btn-outline-secondary" href="admin.php">Management</a></div>
<div class="row g-2 mb-4"><div class="col-md-7"><label class="form-label" for="order-search">Search order or customer</label><input class="form-control" id="order-search" type="search" placeholder="Order number, name, phone"></div><div class="col-md-5"><label class="form-label" for="order-filter">Filter by status</label><select class="form-select" id="order-filter"><option value="">All statuses</option><?php foreach(['pending','confirmed','preparing','ready','out_for_delivery','completed','cancelled','rejected'] as $status): ?><option value="<?=e($status)?>"><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach; ?></select></div></div>
<div class="d-grid gap-3" id="staff-order-list">
<?php foreach($orders as $order): $status=strtolower((string)$order['status']); $choices=$transitions[$status]??[]; if ($status==='ready') $choices=[$order['fulfillment']==='delivery'?'out_for_delivery':'completed']; $searchText=mb_strtolower(implode(' ',[$order['order_number'],$order['customer_name'],$order['phone'],$order['delivery_address'],$order['pickup_location']])); ?>
<article class="card card-body staff-order-card" data-status="<?=e($status)?>" data-search="<?=e($searchText)?>"><div class="d-flex flex-wrap justify-content-between align-items-start gap-2"><div><h2 class="h5 mb-1"><?=e($order['order_number'])?></h2><p class="mb-1 text-secondary small"><?=e(date('M j, Y g:i A',strtotime((string)$order['created_at'])))?> · <?=e(ucfirst((string)$order['fulfillment']))?> · <?=e(strtoupper((string)$order['payment_method']))?></p></div><span class="badge text-bg-secondary"><?=e(ucwords(str_replace('_',' ',$status)))?></span></div>
<div class="row g-3 mt-1"><div class="col-md-6"><h3 class="h6">Customer</h3><p class="mb-1"><?=e((string)$order['customer_name'])?></p><p class="mb-1"><?=e((string)$order['phone'])?></p><p class="mb-0"><?=e((string)($order['delivery_address']?:$order['pickup_location']?:'Pickup location not recorded'))?></p><?php if($order['delivery_instructions']): ?><p class="small text-secondary mt-2 mb-0">Delivery instructions: <?=e((string)$order['delivery_instructions'])?></p><?php endif; ?></div><div class="col-md-6"><h3 class="h6">Order</h3><p class="mb-1"><?=e((string)($order['item_summary']?:'No item details'))?></p><p class="mb-1 small text-secondary">Payment status: <?=e(ucwords(str_replace('_',' ',(string)$order['payment_status'])))?></p><p class="mb-0 fw-semibold">Total: ₱<?=number_format((float)($order['total']??$order['subtotal']),2)?></p><?php if($order['cancellation_reason']): ?><p class="small text-danger mt-2 mb-0">Cancellation reason: <?=e($reasonLabels[$order['cancellation_reason']]??'Recorded reason')?></p><?php endif; ?></div></div>
<div class="d-flex flex-wrap gap-2 mt-3">
<?php if($choices): ?><button type="button" class="btn btn-sm btn-auth" data-update-order="<?=(int)$order['order_id']?>" data-next-status="<?=e($choices[0])?>">Update to <?=e(ucwords(str_replace('_',' ',$choices[0])))?></button><?php endif; ?>
<?php if(!in_array($status,['cancelled','completed','delivered','rejected','failed'],true)): ?><button type="button" class="btn btn-sm btn-outline-danger" data-cancel-order="<?=(int)$order['order_id']?>" data-cancel-number="<?=e($order['order_number'])?>">Cancel order</button><?php endif; ?></div></article>
<?php endforeach; ?></div><p id="order-empty" class="text-secondary mt-3" hidden>No orders match these filters.</p></main>
<div class="modal fade" id="staffStatusModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post" action="staff-order-action.php"><div class="modal-header"><h2 class="modal-title fs-5">Confirm status update</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p id="status-update-copy"></p><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" id="status-order-id"><input type="hidden" name="new_status" id="status-next-value"></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Keep current status</button><button class="btn btn-auth">Confirm status update</button></div></form></div></div></div>
<div class="modal fade" id="staffCancelModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post" action="staff-order-action.php"><div class="modal-header"><h2 class="modal-title fs-5">Cancel order</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p>Cancel <strong id="cancel-order-number"></strong>? Choose a reason to record with the order.</p><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="order_id" id="cancel-order-id"><label class="form-label" for="cancel-reason">Reason</label><select class="form-select" name="reason" id="cancel-reason" required><option value="">Choose a reason</option><?php foreach($reasonLabels as $key=>$label): ?><option value="<?=e($key)?>"><?=e($label)?></option><?php endforeach; ?></select></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Keep order</button><button class="btn btn-danger">Confirm cancellation</button></div></form></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const cancelModal=new bootstrap.Modal('#staffCancelModal'),statusModal=new bootstrap.Modal('#staffStatusModal');document.querySelectorAll('[data-cancel-order]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('cancel-order-id').value=button.dataset.cancelOrder;document.getElementById('cancel-order-number').textContent=button.dataset.cancelNumber;cancelModal.show();}));document.querySelectorAll('[data-update-order]').forEach(button=>button.addEventListener('click',()=>{const label=button.dataset.nextStatus.replaceAll('_',' ');document.getElementById('status-order-id').value=button.dataset.updateOrder;document.getElementById('status-next-value').value=button.dataset.nextStatus;document.getElementById('status-update-copy').textContent='Move order '+button.closest('.staff-order-card').querySelector('h2').textContent+' to '+label+'?';statusModal.show();}));const search=document.getElementById('order-search'),filter=document.getElementById('order-filter'),cards=[...document.querySelectorAll('.staff-order-card')],empty=document.getElementById('order-empty');function apply(){let shown=0;cards.forEach(card=>{const visible=card.dataset.search.includes(search.value.trim().toLowerCase())&&(!filter.value||card.dataset.status===filter.value);card.hidden=!visible;if(visible)shown++;});empty.hidden=shown>0;}search.addEventListener('input',apply);filter.addEventListener('change',apply);apply();});</script>
